import{_ as t,o,c as e,ag as i}from"./chunks/framework.B5ULsuav.js";const q=JSON.parse('{"title":"和光同尘","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-和光同尘.md","filePath":"50-概念资料/dict-和光同尘.md","lastUpdated":1778155802000}'),l={name:"50-概念资料/dict-和光同尘.md"};function r(d,a,h,u,s,n){return o(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="和光同尘" tabindex="-1">和光同尘 <a class="header-anchor" href="#和光同尘" aria-label="Permalink to &quot;和光同尘&quot;">​</a></h1><blockquote><p>传统：道家 | 佛家对应：不执形式 | 儒家对应：合群</p></blockquote><h2 id="了空居士的定义" tabindex="-1">了空居士的定义 <a class="header-anchor" href="#了空居士的定义" aria-label="Permalink to &quot;了空居士的定义&quot;">​</a></h2><p>&quot;和光同尘&quot;就是<strong>收敛锋芒，融入环境</strong>。在光明之处能待，在凡俗之处也能待。不是随波逐流、同流合污，而是<strong>包容一切，但不失自己的本性</strong>。</p><p>了空居士解释为：不张扬、不标榜自己&quot;在修行&quot;——在普通人中做一个好人，在修行人中做一个平常人。佛祖不要特意换袈裟才回答问题，这就是&quot;和光同尘&quot;的示现。</p><h2 id="原话出处" tabindex="-1">原话出处 <a class="header-anchor" href="#原话出处" aria-label="Permalink to &quot;原话出处&quot;">​</a></h2><blockquote><p>&quot;挫其锐，解其纷，和其光，同其尘——收敛锋芒，不张扬，在光明之处能待，在凡俗之处也能待。&quot; — <a href="/liaokongjushi-wisdom/60-原文段落/道德经4章-和光同尘">道德经4章-和光同尘</a></p></blockquote><blockquote><p>&quot;不要说须菩提一提问，佛赶快跑过去穿上袈裟来讲…就没有这种执着。&quot; — <a href="/liaokongjushi-wisdom/60-原文段落/金刚经1分-不执形式">金刚经1分-不执形式</a></p></blockquote><h2 id="常见误解" tabindex="-1">常见误解 <a class="header-anchor" href="#常见误解" aria-label="Permalink to &quot;常见误解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th></tr></thead><tbody><tr><td>和光同尘就是和别人一样吃喝玩乐</td><td>融入环境不代表放纵，是心里清净但外表不标榜</td></tr><tr><td>修行人应该特立独行</td><td>真正的功夫在平常处，不需要用&quot;不一样&quot;来证明</td></tr></tbody></table><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-柔弱">dict-柔弱</a> — 和光同尘是柔弱的外在体现</li><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-处世">dict-处世</a> — 和光同尘是处世的道家智慧版</li><li><a href="/liaokongjushi-wisdom/50-概念资料/dict-自然">dict-自然</a> — 不造作就是和光同尘</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/liaokongjushi-wisdom/10-核心模型/model-圆融中和">model-圆融中和</a> — 和光同尘是处世中的中道实践</li><li><a href="/liaokongjushi-wisdom/10-核心模型/model-对法不执">model-对法不执</a> — 不执著于&quot;修行人&quot;的身份标签</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><p>修行不在外表——不需要穿特定的衣服、用特定的语言来证明&quot;我在修行&quot;。做好事不需让人知道。在人群中和光同尘，心里保持觉照。</p>',16)])])}const m=t(l,[["render",r]]);export{q as __pageData,m as default};
